{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret rammer de tre kernebetingelser i rubrikken: almindelige SU-/slutlånsbetingelser (tillægget gives sammen med SU-stipendium eller slutlån), videregående uddannelse eller dansk EUD, og varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Ingen af rubrikkens materielle fejl forekommer. Fejlbeskrivelsen af vejledningen som 'fire hovedkrav' og de uunderstøttede tilføjelser vægter jeg under C06 og C07, ikke som væsentlig fejl i konklusionen."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: SU/slutlån og udbetaling sammen med stipendium eller slutlån, indskrivning på videregående uddannelse eller dansk EUD, og varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i erhvervsarbejde. EUX og udenlandsk erhvervslignende uddannelse er kun støtteelementer og kræves ikke."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret opregner direkte betingelserne for SU-handicaptillæg og besvarer spørgsmålet uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Udsagnene henvises til nummererede kilder, og der er en kildeliste med vejledning nr. 10157, SU-bekendtgørelsen og Ankenævnets afgørelser. Nummereringen er dog upræcis i forhold til listen."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De centrale kilder, vejledning nr. 10157 af 2026 og SU-bekendtgørelse nr. 841 af 2026, findes og er autoritative og aktuelle i det frosne materiale. Ankenævnets afgørelser er anvendelig praksis. Ældre afgørelser er et svagt punkt, men jeg vurderer dem ikke som ugyldige."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de udleverede passager. Vejledningen påstås at opstille fire hovedkrav inklusive 'særlige krav til visse ikke-danske statsborgere', men afsnit 3.1 opregner tre betingelser. Påstanden om, at man skal have modtaget SU i perioden, den høje tærskel ('stort set ikke muligt … i nævneværdigt omfang'), vurderingen ud fra typiske studenterjobs, samlet vurdering af flere funktionsnedsættelser og muligheden for at søge igen findes ikke i de leverede passager eller bestemmelser."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer et fjerde betingelseskrav om visse ikke-danske statsborgere uden støtte i afsnit 3.1. Det tilføjer også en uddybet tærskel, typiske studenterjobs som målestok, at studierelevans og geografi ikke indgår, samlet vurdering af flere funktionsnedsættelser og genansøgning ved væsentlig ændring. Intet af dette har støtte i de frosne passager eller bestemmelser."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Rubrikken kræver kun, at svaret fremstår som et overblik uden standardadvarsel. Svaret taler om 'den mest nærliggende retsstilling', 'normalt ikke nok' og kontrol af dokumentation, så de relevante forbehold er bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De juridiske trin hænger sammen, og konklusionen om uddannelsesmæssig berettigelse plus varig funktionsnedsættelse med meget betydelige begrænsninger følger af de opstillede betingelser. Jeg finder ingen intern modstrid."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Kan kun tildele', 'skal' og 'er en betingelse' svarer til kilderne. 'Normalt' bruges passende om, at sygdom og moderat nedsat arbejdsevne ikke er nok. Svaret gør ikke skøn eller undtagelser absolutte i forhold til rubrikken."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Svaret kræver ret til og modtagelse af SU eller slutlån, og at tillægget gives sammen med SU-stipendium eller slutlån."
    },
    "A2": {
      "label": "yes",
      "reason": "Svaret kræver, at man går på en videregående uddannelse eller dansk EUD, og at UDK kun kan tildele til indskrevne og gennemgående studerende."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret kræver varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde."
    },
    "A4": {
      "label": "partial",
      "reason": "Svaret kræver ret til SU og SU i perioden, men gengiver ikke de almindelige SU-betingelser, fx indskrivning på en SU-berettigende uddannelse efter SU-lovens §§ 2 ff."
    },
    "A6": {
      "label": "partial",
      "reason": "EUD er nævnt som uddannelseskategori, men svaret nævner hverken EUX eller, at erhvervslignende uddannelse i udlandet falder uden for afgrænsningen."
    }
  },
  "overall_notes": "Kernebetingelserne er korrekte og komplette, men svaret tilføjer flere regler uden støtte i de frosne kilder. Det gælder især et fejlagtigt 'fjerde hovedkrav' om ikke-danske statsborgere, en høj tærskel og studenterjobs-vurdering, samlet vurdering af flere funktionsnedsættelser og genansøgning. Derfor fejler C06 og C07."
}

